script:
frappe.ui.form.on('Project', {
    refresh: function(frm) {
        frm.add_custom_button(__('Get Tasks'), function() {
            if (!frm.doc.__islocal) {
                frappe.call({
                    method: 'frappe.client.get_list',
                    args: {
                        doctype: 'Task',
                        filters: [
                            ['project', '=', frm.doc.name],
                            ['is_group', '=', 0]  // Exclude group tasks
                        ],
                        fields: ['name', 'subject', 'status', 'priority', 'parent_task']  // Include priority and parent_task
                    },
                    callback: function(r) {
                        if (r && r.message.length > 0) {
                            frm.clear_table('custom_task_details');
                            r.message.forEach(function(task) {
                                var row = frm.add_child('custom_task_details');
                                row.task_id = task.name;
                                row.subject = task.subject;
                                row.status = task.status;
                                row.priority = task.priority;  // Populate priority
                                row.parent_task = task.parent_task;  // Populate parent task
                            });
                            frm.refresh_field('custom_task_details');
                        } else {
                            frappe.msgprint(__('No tasks have been created against this project.'));
                        }
                    }
                });
            } else {
                frappe.msgprint(__('Please save the project first to load tasks.'));
            }
        });
    }
});

frappe.ui.form.on('Project', {

    refresh:function(frm){

        let currency = frm.doc.custom_currency;


        if (currency) {
            // Fetch the currency symbol from the Currency doctype
            frappe.db.get_value('Currency', currency, 'symbol').then((res) => {
                if (res && res.message && res.message.symbol) {
                    const symbol = res.message.symbol;
                    const fields_to_update = [
                        'budget_allocated', 'actual_expense',
                        'budget_for_january', 'budget_for_february', 'budget_for_march', 
                        'budget_for_april', 'budget_for_may', 'budget_for_june', 
                        'budget_for_july', 'budget_for_august', 'budget_for_september', 
                        'budget_for_october', 'budget_for_november', 'budget_for_december'
                    ];

                    // Function to capitalize the first letter of each word
                    function capitalizeWords(str) {
                        return str.replace(/_/g, ' ').replace(/\b\w/g, function(l){ return l.toUpperCase() });
                    }

                    // Update the labels of the fields in the child table
                    fields_to_update.forEach(field => {
                        const new_label = `${capitalizeWords(field)} (${symbol})`;
                        frm.fields_dict['custom_task_details'].grid.update_docfield_property(field, 'label', new_label);
                    });

                    // Refresh the field to apply changes
                    frm.refresh_field('custom_task_details');

                    // Unfreeze the screen
                    // frappe.dom.unfreeze();
                }
            });
        }

    },

    custom_currency: function(frm) {

        let currency = frm.doc.custom_currency;


        if (currency) {
            // Fetch the currency symbol from the Currency doctype
            frappe.db.get_value('Currency', currency, 'symbol').then((res) => {
                if (res && res.message && res.message.symbol) {
                    const symbol = res.message.symbol;
                    const fields_to_update = [
                        'budget_allocated', 'actual_expense',
                        'budget_for_january', 'budget_for_february', 'budget_for_march', 
                        'budget_for_april', 'budget_for_may', 'budget_for_june', 
                        'budget_for_july', 'budget_for_august', 'budget_for_september', 
                        'budget_for_october', 'budget_for_november', 'budget_for_december'
                    ];

                    // Function to capitalize the first letter of each word
                    function capitalizeWords(str) {
                        return str.replace(/_/g, ' ').replace(/\b\w/g, function(l){ return l.toUpperCase() });
                    }

                    // Update the labels of the fields in the child table
                    fields_to_update.forEach(field => {
                        const new_label = `${capitalizeWords(field)} (${symbol})`;
                        frm.fields_dict['custom_task_details'].grid.update_docfield_property(field, 'label', new_label);
                    });

                    // Refresh the field to apply changes
                    frm.refresh_field('custom_task_details');

                    // Unfreeze the screen
                    // frappe.dom.unfreeze();
                }
            });
        }
    }
});

frappe.ui.form.on('Subject', {
    setup: function(frm) {
        frm.set_query('task', function(doc) {
            return {
                filters: {
                    'project': doc.project
                }
            };
        });
    },

    project: function(frm) {
        // Clear the task field when project changes
        frm.set_value('task', '');
    }
});
